  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build node map and children lists
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        parent_id = n.get('parent')
        if parent_id is not None:
            children.setdefault(parent_id, []).append(n['id'])

    # Quick feasibility check: each required symbol must appear in at least one node
    symbol_nodes = {}
    for n in nodes:
        symbol_nodes.setdefault(n['symbol'], []).append(n['id'])
    for sym in required_symbols:
        if sym not in symbol_nodes:
            raise ValueError(f"Required symbol '{sym}' not present in any node")

    # Sort nodes by depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    removed = set()
    removal_order = []

    def required_symbols_present():
        # Check each required symbol has at least one node not removed
        for sym in required_symbols:
            found = False
            for nid in symbol_nodes[sym]:
                if nid not in removed:
                    found = True
                    break
            if not found:
                return False
        return True

    for n in sorted_nodes:
        nid = n['id']
        # Skip if already removed, not removable, root, or required symbol
        if nid in removed:
            continue
        if nid == 'root':
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        # Check that all children are already removed
        child_ids = children.get(nid, [])
        if any(cid not in removed for cid in child_ids):
            continue
        # Tentatively remove
        removed.add(nid)
        if required_symbols_present():
            removal_order.append(nid)
        else:
            removed.remove(nid)

    retained = sorted([n['id'] for n in nodes if n['id'] not in removed])
    return {
        'removed_node_ids': removal_order,
        'retained_node_ids': retained
    }"
